/**
 * CopilotDriver — `ProviderDriver` for the GitHub Copilot SDK runtime.
 *
 * Follows the same pattern as ClaudeDriver: a plain value whose `create()`
 * returns one `ProviderInstance` bundling `snapshot` / `adapter` /
 * `textGeneration` closures captured over the per-instance `CopilotSettings`.
 *
 * @module CopilotDriver
 */
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import {
  CopilotSettings,
  ProviderDriverKind,
  type ProviderInstanceId,
  type ServerProvider,
} from "@t3tools/contracts";

import { ServerConfig } from "../../config.ts";
import { ServerSettingsService } from "../../serverSettings.ts";
import { makeCopilotTextGeneration } from "../../textGeneration/CopilotTextGeneration.ts";
import { makeCopilotAdapter, type CopilotAdapterLiveOptions } from "../Layers/CopilotAdapter.ts";
import { checkCopilotProviderStatus } from "../Layers/CopilotProvider.ts";
import { makeManagedServerProvider } from "../makeManagedServerProvider.ts";
import { makeManualOnlyProviderMaintenanceCapabilities } from "../providerMaintenance.ts";
import { ProviderDriverError } from "../Errors.ts";
import {
  type ProviderDriver,
  type ProviderInstance,
  defaultProviderContinuationIdentity,
} from "../ProviderDriver.ts";
import { ProviderEventLoggers } from "../Layers/ProviderEventLoggers.ts";
import { buildServerProvider } from "../providerSnapshot.ts";
import type { ServerProviderDraft } from "../providerSnapshot.ts";

const DRIVER_KIND = ProviderDriverKind.make("copilot");
const SNAPSHOT_REFRESH_INTERVAL = "120 seconds";

const COPILOT_PRESENTATION = {
  displayName: "GitHub Copilot",
} as const;

const makePendingCopilotProvider = (): ServerProviderDraft =>
  buildServerProvider({
    presentation: COPILOT_PRESENTATION,
    enabled: false,
    checkedAt: DateTime.formatIso(DateTime.nowUnsafe()),
    models: [],
    probe: {
      installed: false,
      version: null,
      status: "error",
      auth: { status: "unknown" },
      message: "Checking GitHub Copilot availability...",
    },
  });

const withInstanceIdentity =
  (input: {
    readonly instanceId: ProviderInstance["instanceId"];
    readonly displayName: string | undefined;
    readonly accentColor: string | undefined;
    readonly continuationGroupKey: string;
  }) =>
  (snapshot: ServerProviderDraft): ServerProvider => ({
    ...snapshot,
    instanceId: input.instanceId,
    driver: DRIVER_KIND,
    ...(input.displayName ? { displayName: input.displayName } : {}),
    ...(input.accentColor ? { accentColor: input.accentColor } : {}),
    continuation: { groupKey: input.continuationGroupKey },
  });

export type CopilotDriverEnv = ServerConfig | ServerSettingsService | ProviderEventLoggers;

export const CopilotDriver: ProviderDriver<CopilotSettings, CopilotDriverEnv> = {
  driverKind: DRIVER_KIND,
  metadata: {
    displayName: "GitHub Copilot",
    supportsMultipleInstances: false,
  },
  configSchema: CopilotSettings,
  defaultConfig: (): CopilotSettings => Schema.decodeSync(CopilotSettings)({}),
  create: ({ instanceId, displayName, accentColor, enabled, config }) =>
    Effect.gen(function* () {
      const eventLoggers = yield* ProviderEventLoggers;
      const fallbackContinuationIdentity = defaultProviderContinuationIdentity({
        driverKind: DRIVER_KIND,
        instanceId,
      });
      const effectiveConfig = { ...config, enabled } satisfies CopilotSettings;
      const continuationGroupKey = `copilot:${instanceId}`;
      const stampIdentity = withInstanceIdentity({
        instanceId,
        displayName,
        accentColor,
        continuationGroupKey,
      });

      const maintenanceCapabilities = makeManualOnlyProviderMaintenanceCapabilities({
        provider: DRIVER_KIND,
        packageName: "@github/copilot-sdk",
      });

      const adapterOptions: CopilotAdapterLiveOptions = {
        ...(eventLoggers.native ? { nativeEventLogger: eventLoggers.native } : {}),
      };
      const adapter = yield* makeCopilotAdapter(adapterOptions);
      const textGeneration = yield* makeCopilotTextGeneration;

      const checkProvider = checkCopilotProviderStatus(effectiveConfig).pipe(
        Effect.map(stampIdentity),
      );

      const snapshot = yield* makeManagedServerProvider<CopilotSettings>({
        maintenanceCapabilities,
        getSettings: Effect.succeed(effectiveConfig),
        streamSettings: Stream.never,
        haveSettingsChanged: () => false,
        initialSnapshot: () => Effect.succeed(stampIdentity(makePendingCopilotProvider())),
        checkProvider,
        refreshInterval: SNAPSHOT_REFRESH_INTERVAL,
      }).pipe(
        Effect.mapError(
          (cause) =>
            new ProviderDriverError({
              driver: DRIVER_KIND,
              instanceId,
              detail: `Failed to build Copilot snapshot: ${cause.message ?? String(cause)}`,
              cause,
            }),
        ),
      );

      return {
        instanceId,
        driverKind: DRIVER_KIND,
        continuationIdentity: {
          ...fallbackContinuationIdentity,
          continuationKey: continuationGroupKey,
        },
        displayName,
        accentColor,
        enabled,
        snapshot,
        adapter,
        textGeneration,
      } satisfies ProviderInstance;
    }),
};

import { randomUUID } from "node:crypto";

import {
  type ModelSelection,
  type ServerProviderSkill,
  EventId,
  type ProviderApprovalDecision,
  ProviderDriverKind,
  ProviderItemId,
  type ProviderRuntimeEvent,
  type ProviderSession,
  type ProviderTurnStartResult,
  type ProviderUserInputAnswers,
  RuntimeItemId,
  RuntimeRequestId,
  RuntimeTaskId,
  ThreadId,
  TurnId,
} from "@t3tools/contracts";
import {
  CopilotClient,
  type CopilotClientOptions,
  type ModelInfo,
  type PermissionRequest,
  type PermissionRequestResult,
  type SessionEvent,
} from "@github/copilot-sdk";

type ReasoningEffort = "low" | "medium" | "high" | "xhigh";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Queue from "effect/Queue";
import * as Stream from "effect/Stream";

import { resolveAttachmentPath } from "../../attachmentStore.ts";
import { ServerConfig } from "../../config.ts";
import { ServerSettingsService } from "../../serverSettings.ts";
import {
  ProviderAdapterProcessError,
  ProviderAdapterRequestError,
  ProviderAdapterSessionNotFoundError,
  ProviderAdapterValidationError,
} from "../Errors.ts";
import { type EventNdjsonLogger } from "./EventNdjsonLogger.ts";
import {
  assistantUsageFields,
  beginCopilotTurn,
  clearTurnTracking,
  completionTurnRefs,
  isCopilotTurnTerminalEvent,
  markTurnAwaitingCompletion,
  recordTurnUsage,
  type CopilotTurnTrackingState,
} from "./copilotTurnTracking.ts";
import { loadCopilotMcpServers } from "./copilotMcpServers.ts";
import { normalizeCopilotCliPathOverride, resolveBundledCopilotCliPath } from "./copilotCliPath.ts";
import { CopilotAdapter, type CopilotAdapterShape } from "../Services/CopilotAdapter.ts";
import type {
  ProviderThreadSnapshot,
  ProviderThreadTurnSnapshot,
} from "../Services/ProviderAdapter.ts";

const PROVIDER = ProviderDriverKind.make("copilot");
const USER_INPUT_QUESTION_ID = "answer";
const USER_INPUT_QUESTION_HEADER = "Question";

export interface CopilotAdapterLiveOptions {
  readonly nativeEventLogger?: EventNdjsonLogger;
  readonly clientFactory?: (options: CopilotClientOptions) => CopilotClientHandle;
}

interface PendingApprovalRequest {
  readonly request: CopilotPermissionRequest;
  readonly requestType:
    | "command_execution_approval"
    | "file_change_approval"
    | "file_read_approval"
    | "dynamic_tool_call"
    | "unknown";
  readonly turnId: TurnId | undefined;
  readonly resolve: (result: CopilotPermissionRequestResult) => void;
}

interface CopilotUserInputRequest {
  readonly question: string;
  readonly choices?: ReadonlyArray<string>;
  readonly allowFreeform?: boolean;
}

interface CopilotUserInputResponse {
  readonly answer: string;
  readonly wasFreeform: boolean;
}

interface PendingUserInputRequest {
  readonly request: CopilotUserInputRequest;
  readonly turnId: TurnId | undefined;
  readonly resolve: (result: CopilotUserInputResponse) => void;
}

interface CopilotSessionConfiguration {
  readonly model: string | undefined;
  readonly reasoningEffort: ReasoningEffort | undefined;
}

// @github/copilot-sdk@0.3.0 uses the newer permission decision protocol at runtime,
// but the package root still exports legacy PermissionRequest/PermissionRequestResult types.
// Keep a local structural view until the SDK's public typings catch up.
type CopilotPermissionRequest =
  | {
      readonly kind: "shell";
      readonly toolCallId?: string;
      readonly canOfferSessionApproval: boolean;
      readonly commands: ReadonlyArray<{
        readonly identifier: string;
        readonly readOnly: boolean;
      }>;
      readonly fullCommandText: string;
      readonly hasWriteFileRedirection: boolean;
      readonly intention: string;
      readonly possiblePaths: ReadonlyArray<string>;
      readonly possibleUrls: ReadonlyArray<{
        readonly url: string;
      }>;
      readonly warning?: string;
    }
  | {
      readonly kind: "write";
      readonly toolCallId?: string;
      readonly canOfferSessionApproval: boolean;
      readonly diff: string;
      readonly fileName: string;
      readonly intention: string;
      readonly newFileContents?: string;
    }
  | {
      readonly kind: "read";
      readonly toolCallId?: string;
      readonly intention: string;
      readonly path: string;
    }
  | {
      readonly kind: "mcp";
      readonly toolCallId?: string;
      readonly args?: Record<string, unknown>;
      readonly readOnly: boolean;
      readonly serverName: string;
      readonly toolName: string;
      readonly toolTitle: string;
    }
  | {
      readonly kind: "url";
      readonly toolCallId?: string;
      readonly intention: string;
      readonly url: string;
    }
  | {
      readonly kind: "memory";
      readonly toolCallId?: string;
      readonly action?: "store" | "vote";
      readonly citations?: string;
      readonly direction?: "upvote" | "downvote";
      readonly fact: string;
      readonly reason?: string;
      readonly subject?: string;
    }
  | {
      readonly kind: "custom-tool";
      readonly toolCallId?: string;
      readonly args?: Record<string, unknown>;
      readonly toolDescription: string;
      readonly toolName: string;
    }
  | {
      readonly kind: "hook";
      readonly toolCallId?: string;
      readonly hookMessage?: string;
      readonly toolArgs?: Record<string, unknown>;
      readonly toolName: string;
    };

type CopilotPermissionSessionApproval =
  | {
      readonly kind: "commands";
      readonly commandIdentifiers: ReadonlyArray<string>;
    }
  | {
      readonly kind: "read";
    }
  | {
      readonly kind: "write";
    }
  | {
      readonly kind: "mcp";
      readonly serverName: string;
      readonly toolName: string | null;
    }
  | {
      readonly kind: "memory";
    }
  | {
      readonly kind: "custom-tool";
      readonly toolName: string;
    };

type CopilotPermissionRequestResult =
  | {
      readonly kind: "approve-once";
    }
  | {
      readonly kind: "approve-for-session";
      readonly approval: CopilotPermissionSessionApproval;
    }
  | {
      readonly kind: "reject";
      readonly feedback?: string;
    }
  | {
      readonly kind: "user-not-available";
    }
  | {
      readonly kind: "no-result";
    };

function toSdkPermissionRequestResult(
  result: CopilotPermissionRequestResult,
): PermissionRequestResult {
  return result as PermissionRequestResult;
}

interface ActiveCopilotSession extends CopilotTurnTrackingState {
  readonly client: CopilotClientHandle;
  session: CopilotSessionHandle;
  readonly threadId: ThreadId;
  readonly createdAt: string;
  readonly runtimeMode: ProviderSession["runtimeMode"];
  cwd: string | undefined;
  configDir: string | undefined;
  model: string | undefined;
  reasoningEffort: ReasoningEffort | undefined;
  interactionMode: "default" | "plan" | undefined;
  updatedAt: string;
  turnSentAt: string | undefined;
  lastError: string | undefined;
  toolTitlesByCallId: Map<string, string>;
  pendingApprovalResolvers: Map<string, PendingApprovalRequest>;
  pendingUserInputResolvers: Map<string, PendingUserInputRequest>;
  unsubscribe: () => void;
}

// ── Copilot Skill Discovery ─────────────────────────────────────────────

/**
 * Module-level store for discovered Copilot skills.
 * Populated from `session.skills_loaded` events and `rpc.skills.list()`.
 * Read by `CopilotProvider.ts` during snapshot enrichment.
 * Merged by name to support multi-session and event/RPC race tolerance.
 */
let discoveredCopilotSkills: ReadonlyArray<ServerProviderSkill> = [];

/** Get the most recently discovered skills (read by CopilotProvider). */
export function getCopilotDiscoveredSkills(): ReadonlyArray<ServerProviderSkill> {
  return discoveredCopilotSkills;
}

/** Expected response shape from rpc.skills.list() */
interface CopilotSkillsListResponse {
  skills: ReadonlyArray<{
    name: string;
    description?: string;
    source?: string;
    userInvocable?: boolean;
    enabled?: boolean;
    path?: string;
  }>;
}

/** Typed RPC interface for skills operations */
interface CopilotSkillsRpc {
  skills?: {
    list?: () => Promise<CopilotSkillsListResponse>;
    enable?: (params: { name: string }) => Promise<unknown>;
    disable?: (params: { name: string }) => Promise<unknown>;
    reload?: () => Promise<unknown>;
  };
}

/**
 * Merge incoming skills with existing discovered skills by name.
 * Incoming skills replace existing ones with the same name; skills
 * from other sessions/sources are preserved.
 */
function mergeDiscoveredSkills(incoming: ReadonlyArray<ServerProviderSkill>): void {
  const byName = new Map(discoveredCopilotSkills.map((s) => [s.name, s]));
  for (const skill of incoming) {
    byName.set(skill.name, skill);
  }
  discoveredCopilotSkills = Array.from(byName.values());
}

function mapSdkSkillToServerProviderSkill(skill: {
  name: string;
  description?: string;
  source?: string;
  userInvocable?: boolean;
  enabled?: boolean;
  path?: string;
}): ServerProviderSkill | null {
  // Filter out non-user-invocable skills — they shouldn't appear in $ autocomplete
  if (skill.userInvocable === false) {
    return null;
  }
  const name = skill.name.trim();
  const displayName = name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  return {
    name,
    path: skill.path?.trim() || name,
    enabled: skill.enabled !== false,
    ...(skill.description
      ? { description: skill.description, shortDescription: skill.description }
      : {}),
    ...(skill.source ? { scope: skill.source } : {}),
    ...(displayName !== name ? { displayName } : {}),
  };
}

type CopilotSessionHandle = Awaited<ReturnType<CopilotClient["createSession"]>>;

type CopilotClientHandle = Pick<
  CopilotClient,
  "start" | "listModels" | "createSession" | "resumeSession" | "stop"
>;

function toMessage(cause: unknown, fallback: string): string {
  if (cause instanceof Error && cause.message.length > 0) {
    return cause.message;
  }
  return fallback;
}

function makeEventId(prefix: string) {
  return EventId.make(`${prefix}-${randomUUID()}`);
}

function toTurnId(value: string | undefined): TurnId | undefined {
  if (!value || value.trim().length === 0) return undefined;
  return TurnId.make(value);
}

function toRuntimeItemId(value: string | undefined) {
  if (!value || value.trim().length === 0) return undefined;
  return RuntimeItemId.make(value);
}

function toProviderItemId(value: string | undefined) {
  if (!value || value.trim().length === 0) return undefined;
  return ProviderItemId.make(value);
}

function toRuntimeRequestId(value: string | undefined) {
  if (!value || value.trim().length === 0) return undefined;
  return RuntimeRequestId.make(value);
}

function toRuntimeTaskId(value: string | undefined) {
  if (!value || value.trim().length === 0) return undefined;
  return RuntimeTaskId.make(value);
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
  return value as Record<string, unknown>;
}

function normalizeString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

function trimToUndefined(value: string | undefined): string | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function toNonNegativeInt(value: number | undefined) {
  return value === undefined || !Number.isFinite(value)
    ? undefined
    : Math.max(0, Math.floor(value));
}

function toPositiveInt(value: number | undefined) {
  const normalized = toNonNegativeInt(value);
  return normalized && normalized > 0 ? normalized : undefined;
}

function mapSessionUsageInfo(usage: Extract<SessionEvent, { type: "session.usage_info" }>["data"]) {
  return {
    usedTokens: toNonNegativeInt(usage.currentTokens) ?? 0,
    ...(toNonNegativeInt(usage.currentTokens) !== undefined
      ? { totalProcessedTokens: toNonNegativeInt(usage.currentTokens) }
      : {}),
    ...(toPositiveInt(usage.tokenLimit) ? { maxTokens: toPositiveInt(usage.tokenLimit) } : {}),
  };
}

function mapAssistantUsage(usage: Extract<SessionEvent, { type: "assistant.usage" }>["data"]) {
  const inputTokens = toNonNegativeInt(usage.inputTokens);
  const outputTokens = toNonNegativeInt(usage.outputTokens);
  const cachedInputTokens = toNonNegativeInt(usage.cacheReadTokens);
  const durationMs = toNonNegativeInt(usage.duration);
  const usedTokens = (inputTokens ?? 0) + (outputTokens ?? 0) + (cachedInputTokens ?? 0);
  return {
    usedTokens,
    totalProcessedTokens: usedTokens,
    ...(inputTokens !== undefined ? { inputTokens } : {}),
    ...(cachedInputTokens !== undefined ? { cachedInputTokens } : {}),
    ...(outputTokens !== undefined ? { outputTokens } : {}),
    ...(usedTokens > 0 ? { lastUsedTokens: usedTokens } : {}),
    ...(inputTokens !== undefined ? { lastInputTokens: inputTokens } : {}),
    ...(cachedInputTokens !== undefined ? { lastCachedInputTokens: cachedInputTokens } : {}),
    ...(outputTokens !== undefined ? { lastOutputTokens: outputTokens } : {}),
    ...(durationMs !== undefined ? { durationMs } : {}),
  };
}

function mapSupportedModelsById(models: ReadonlyArray<ModelInfo>) {
  return new Map(models.map((model) => [model.id, model]));
}

function getCopilotReasoningEffortFromSelection(
  modelSelection: ModelSelection | undefined,
): ReasoningEffort | undefined {
  if (!modelSelection) {
    return undefined;
  }
  const effortEntry = modelSelection.options?.find(
    (o: { id: string; value: string | boolean }) => o.id === "effort" || o.id === "reasoningEffort",
  );
  const reasoningEffort = typeof effortEntry?.value === "string" ? normalizeString(effortEntry.value) : undefined;
  return reasoningEffort === "low" ||
    reasoningEffort === "medium" ||
    reasoningEffort === "high" ||
    reasoningEffort === "xhigh"
    ? reasoningEffort
    : undefined;
}

function extractResumeSessionId(resumeCursor: unknown): string | undefined {
  if (typeof resumeCursor === "string" && resumeCursor.trim().length > 0) {
    return resumeCursor.trim();
  }
  const record = asRecord(resumeCursor);
  const sessionId = normalizeString(record?.sessionId);
  return sessionId;
}

function toCopilotSessionMode(interactionMode: "default" | "plan"): "interactive" | "plan" {
  return interactionMode === "plan" ? "plan" : "interactive";
}

function toInteractionMode(mode: string): "default" | "plan" {
  return mode === "plan" ? "plan" : "default";
}

function approvalDecisionToPermissionResult(
  decision: ProviderApprovalDecision,
  request?: CopilotPermissionRequest,
): CopilotPermissionRequestResult {
  const sessionApprovalFromPermissionRequest = () => {
    if (!request) {
      return undefined;
    }

    switch (request.kind) {
      case "shell": {
        if (!request.canOfferSessionApproval) {
          return undefined;
        }
        const commandIdentifiers = request.commands
          .map((command) => trimToUndefined(command.identifier))
          .filter((identifier): identifier is string => identifier !== undefined);
        return commandIdentifiers.length > 0
          ? {
              kind: "approve-for-session" as const,
              approval: {
                kind: "commands" as const,
                commandIdentifiers,
              },
            }
          : undefined;
      }
      case "write":
        return request.canOfferSessionApproval
          ? {
              kind: "approve-for-session" as const,
              approval: { kind: "write" as const },
            }
          : undefined;
      case "read":
        return {
          kind: "approve-for-session" as const,
          approval: { kind: "read" as const },
        };
      case "mcp":
        return {
          kind: "approve-for-session" as const,
          approval: {
            kind: "mcp" as const,
            serverName: request.serverName,
            toolName: request.toolName,
          },
        };
      case "memory":
        return {
          kind: "approve-for-session" as const,
          approval: { kind: "memory" as const },
        };
      case "custom-tool":
        return {
          kind: "approve-for-session" as const,
          approval: {
            kind: "custom-tool" as const,
            toolName: request.toolName,
          },
        };
      default:
        return undefined;
    }
  };

  switch (decision) {
    case "accept":
      return { kind: "approve-once" };
    case "acceptForSession":
      return sessionApprovalFromPermissionRequest() ?? { kind: "approve-once" };
    case "decline":
    case "cancel":
    default:
      return { kind: "reject" };
  }
}

function requestTypeFromPermissionRequest(request: CopilotPermissionRequest) {
  switch (request.kind) {
    case "shell":
      return "command_execution_approval" as const;
    case "write":
      return "file_change_approval" as const;
    case "read":
      return "file_read_approval" as const;
    case "mcp":
    case "custom-tool":
      return "dynamic_tool_call" as const;
    default:
      return "unknown" as const;
  }
}

function requestDetailFromPermissionRequest(request: CopilotPermissionRequest): string | undefined {
  switch (request.kind) {
    case "shell":
      return trimToUndefined(String(request.fullCommandText ?? ""));
    case "write":
      return trimToUndefined(String(request.fileName ?? request.intention ?? ""));
    case "read":
      return trimToUndefined(String(request.path ?? request.intention ?? ""));
    case "mcp":
      return trimToUndefined(String(request.toolTitle ?? request.toolName ?? ""));
    case "url":
      return trimToUndefined(String(request.url ?? request.intention ?? ""));
    case "custom-tool":
      return trimToUndefined(String(request.toolName ?? request.toolDescription ?? ""));
    default:
      return undefined;
  }
}

function itemTypeFromToolEvent(event: Extract<SessionEvent, { type: "tool.execution_start" }>) {
  return event.data.mcpToolName ? "mcp_tool_call" : "dynamic_tool_call";
}

function toolDetailFromEvent(data: {
  readonly toolName?: string;
  readonly mcpToolName?: string;
  readonly mcpServerName?: string;
}) {
  return trimToUndefined(
    [data.mcpServerName, data.mcpToolName ?? data.toolName].filter(Boolean).join(" / "),
  );
}

function withRefs(input: {
  readonly threadId: ThreadId;
  readonly eventId: EventId;
  readonly createdAt: string;
  readonly turnId: TurnId | undefined;
  readonly providerTurnId?: TurnId | undefined;
  readonly itemId: string | undefined;
  readonly requestId: string | undefined;
  readonly rawMethod: string | undefined;
  readonly rawPayload: unknown;
}): Omit<ProviderRuntimeEvent, "type" | "payload"> {
  const providerTurnId = input.providerTurnId ?? input.turnId;
  const providerItemId = toProviderItemId(input.itemId);
  const providerRequestId = trimToUndefined(input.requestId);
  return {
    eventId: input.eventId,
    provider: PROVIDER,
    threadId: input.threadId,
    createdAt: input.createdAt,
    ...(input.turnId ? { turnId: input.turnId } : {}),
    ...(input.itemId ? { itemId: toRuntimeItemId(input.itemId) } : {}),
    ...(input.requestId ? { requestId: toRuntimeRequestId(input.requestId) } : {}),
    ...(providerTurnId || providerItemId || providerRequestId
      ? {
          providerRefs: {
            ...(providerTurnId ? { providerTurnId } : {}),
            ...(providerItemId ? { providerItemId } : {}),
            ...(providerRequestId ? { providerRequestId } : {}),
          },
        }
      : {}),
    raw: {
      source: input.rawMethod ? "copilot.sdk.session-event" : "copilot.sdk.synthetic",
      ...(input.rawMethod ? { method: input.rawMethod } : {}),
      payload: input.rawPayload,
    },
  };
}

function mapHistoryToTurns(
  threadId: ThreadId,
  events: ReadonlyArray<SessionEvent>,
): ProviderThreadSnapshot {
  const turns: Array<ProviderThreadTurnSnapshot> = [];
  let current: { id: TurnId; items: Array<unknown> } | undefined;

  for (const event of events) {
    if (event.type === "assistant.turn_start") {
      current = {
        id: TurnId.make(event.data.turnId),
        items: [event],
      };
      turns.push(current);
      continue;
    }

    if (!current) {
      continue;
    }

    current.items.push(event);
    if (isCopilotTurnTerminalEvent(event)) {
      current = undefined;
    }
  }

  return {
    threadId,
    turns: turns.map((turn) => ({
      id: turn.id,
      items: turn.items,
    })),
  };
}

function makeSyntheticEvent(
  threadId: ThreadId,
  type: ProviderRuntimeEvent["type"],
  payload: ProviderRuntimeEvent["payload"],
  extra?: {
    readonly turnId?: TurnId | undefined;
    readonly itemId?: string | undefined;
    readonly requestId?: string | undefined;
  },
): ProviderRuntimeEvent {
  return {
    ...withRefs({
      threadId,
      eventId: makeEventId("copilot-synthetic"),
      createdAt: DateTime.formatIso(DateTime.nowUnsafe()),
      turnId: extra?.turnId,
      itemId: extra?.itemId,
      requestId: extra?.requestId,
      rawMethod: undefined,
      rawPayload: payload,
    }),
    type,
    payload,
  } as ProviderRuntimeEvent;
}

function resolveUserInputAnswer(
  pending: PendingUserInputRequest,
  answers: ProviderUserInputAnswers,
): CopilotUserInputResponse {
  const direct = answers[USER_INPUT_QUESTION_ID];
  const candidate =
    typeof direct === "string"
      ? direct
      : Object.values(answers).find((value): value is string => typeof value === "string");
  const answer = trimToUndefined(candidate) ?? "";
  return {
    answer,
    wasFreeform: !pending.request.choices?.includes(answer),
  };
}

function createSessionRecord(input: {
  readonly threadId: ThreadId;
  readonly client: CopilotClientHandle;
  readonly session: CopilotSessionHandle;
  readonly runtimeMode: ProviderSession["runtimeMode"];
  readonly pendingApprovalResolvers: Map<string, PendingApprovalRequest>;
  readonly pendingUserInputResolvers: Map<string, PendingUserInputRequest>;
  readonly cwd: string | undefined;
  readonly configDir: string | undefined;
  readonly model: string | undefined;
  readonly reasoningEffort: ReasoningEffort | undefined;
}): ActiveCopilotSession {
  return {
    client: input.client,
    session: input.session,
    threadId: input.threadId,
    createdAt: DateTime.formatIso(DateTime.nowUnsafe()),
    runtimeMode: input.runtimeMode,
    cwd: input.cwd,
    configDir: input.configDir,
    model: input.model,
    reasoningEffort: input.reasoningEffort,
    interactionMode: undefined,
    updatedAt: DateTime.formatIso(DateTime.nowUnsafe()),
    turnSentAt: undefined,
    lastError: undefined,
    currentTurnId: undefined,
    currentProviderTurnId: undefined,
    pendingCompletionTurnId: undefined,
    pendingCompletionProviderTurnId: undefined,
    pendingTurnIds: [],
    pendingTurnUsage: undefined,
    toolTitlesByCallId: new Map(),
    pendingApprovalResolvers: input.pendingApprovalResolvers,
    pendingUserInputResolvers: input.pendingUserInputResolvers,
    unsubscribe: () => undefined,
  };
}

export const makeCopilotAdapter = (options?: CopilotAdapterLiveOptions) =>
  Effect.gen(function* () {
    const serverConfig = yield* ServerConfig;
    const serverSettings = yield* ServerSettingsService;
    const nativeEventLogger = options?.nativeEventLogger;
    const runtimeEventQueue = yield* Queue.unbounded<ProviderRuntimeEvent>();
    const sessions = new Map<ThreadId, ActiveCopilotSession>();
    const services = yield* Effect.context<never>();
    const runPromise = Effect.runPromiseWith(services);

    const emitRuntimeEvents = (events: ReadonlyArray<ProviderRuntimeEvent>) =>
      runPromise(Queue.offerAll(runtimeEventQueue, events).pipe(Effect.asVoid)).catch(
        () => undefined,
      );

    const writeNativeEvent = (threadId: ThreadId, event: SessionEvent) => {
      if (!nativeEventLogger) return Promise.resolve();
      return runPromise(nativeEventLogger.write(event, threadId)).catch(() => undefined);
    };

    const currentSyntheticTurnId = (record: ActiveCopilotSession) =>
      completionTurnRefs(record).turnId ?? record.currentTurnId;

    const syncInteractionMode = (
      record: ActiveCopilotSession,
      interactionMode: "default" | "plan",
    ) => {
      if (record.interactionMode === interactionMode) {
        return Effect.void;
      }
      return Effect.tryPromise({
        try: async () => {
          await record.session.rpc.mode.set({
            mode: toCopilotSessionMode(interactionMode),
          });
          record.interactionMode = interactionMode;
        },
        catch: (cause) =>
          new ProviderAdapterRequestError({
            provider: PROVIDER,
            method: "session.mode.set",
            detail: toMessage(cause, "Failed to switch GitHub Copilot interaction mode."),
            cause,
          }),
      });
    };

    const emitLatestProposedPlan = (record: ActiveCopilotSession) =>
      Effect.tryPromise({
        try: () => record.session.rpc.plan.read(),
        catch: (cause) =>
          new ProviderAdapterRequestError({
            provider: PROVIDER,
            method: "session.plan.read",
            detail: toMessage(cause, "Failed to read the GitHub Copilot plan."),
            cause,
          }),
      }).pipe(
        Effect.flatMap((plan) => {
          const planMarkdown = trimToUndefined(plan.content ?? undefined);
          if (!plan.exists || !planMarkdown) {
            return Effect.void;
          }
          return Queue.offer(
            runtimeEventQueue,
            makeSyntheticEvent(
              record.threadId,
              "turn.proposed.completed",
              {
                planMarkdown,
              },
              { turnId: currentSyntheticTurnId(record) },
            ),
          ).pipe(Effect.asVoid);
        }),
      );

    const mapSessionEvent = (
      record: ActiveCopilotSession,
      event: SessionEvent,
    ): ReadonlyArray<ProviderRuntimeEvent> => {
      const currentTurnId = record.currentTurnId;
      const currentProviderTurnId = record.currentProviderTurnId;
      const resolveOrchestrationTurnId = (
        providerTurnId: TurnId | undefined,
      ): TurnId | undefined => {
        if (providerTurnId && currentProviderTurnId && providerTurnId === currentProviderTurnId) {
          return currentTurnId ?? providerTurnId;
        }
        return currentTurnId ?? providerTurnId;
      };
      const base = (input?: {
        readonly turnId?: TurnId | undefined;
        readonly providerTurnId?: TurnId | undefined;
        readonly itemId?: string | undefined;
        readonly requestId?: string | undefined;
      }) =>
        withRefs({
          threadId: record.threadId,
          eventId: EventId.make(event.id),
          createdAt: event.timestamp,
          turnId: resolveOrchestrationTurnId(input?.providerTurnId ?? input?.turnId),
          providerTurnId: input?.providerTurnId ?? input?.turnId,
          itemId: input?.itemId,
          requestId: input?.requestId,
          rawMethod: event.type,
          rawPayload: event,
        });

      switch (event.type) {
        case "session.start":
        case "session.resume":
          return [
            {
              ...base(),
              type: "session.started",
              payload: {
                message:
                  event.type === "session.resume"
                    ? "Resumed GitHub Copilot session"
                    : "Started GitHub Copilot session",
                resume: event.data,
              },
            },
            {
              ...base(),
              type: "thread.started",
              payload: {
                providerThreadId:
                  event.type === "session.start" ? event.data.sessionId : record.session.sessionId,
              },
            },
          ];
        case "session.info":
          return [
            {
              ...base(),
              type: "runtime.warning",
              payload: {
                message: event.data.message,
                detail: event.data,
              },
            },
          ];
        case "session.warning":
          return [
            {
              ...base(),
              type: "runtime.warning",
              payload: {
                message: event.data.message,
                detail: event.data,
              },
            },
          ];
        case "session.error":
          return [
            {
              ...base(),
              type: "runtime.error",
              payload: {
                message: event.data.message,
                class: "provider_error",
                detail: event.data,
              },
            },
            {
              ...base(),
              type: "session.state.changed",
              payload: {
                state: "error",
                reason: "session.error",
                detail: event.data,
              },
            },
          ];
        case "session.idle": {
          const idleCompletionRefs = completionTurnRefs(record);
          const idleCompletionEvents: ProviderRuntimeEvent[] =
            idleCompletionRefs.turnId || idleCompletionRefs.providerTurnId
              ? [
                  {
                    ...base(idleCompletionRefs),
                    type: "turn.completed",
                    payload: {
                      state: "completed",
                      ...assistantUsageFields(record.pendingTurnUsage),
                    },
                  } satisfies ProviderRuntimeEvent,
                ]
              : [];
          return [
            ...idleCompletionEvents,
            {
              ...base(),
              type: "session.state.changed",
              payload: {
                state: "ready",
                reason: "session.idle",
              },
            },
            {
              ...base(),
              type: "thread.state.changed",
              payload: {
                state: "idle",
                detail: event.data,
              },
            },
          ];
        }
        case "session.title_changed": {
          const titleMetadata = asRecord(event.data);
          return [
            {
              ...base(),
              type: "thread.metadata.updated",
              payload: {
                name: event.data.title,
                ...(titleMetadata ? { metadata: titleMetadata } : {}),
              },
            },
          ];
        }
        case "session.model_change":
          return [
            {
              ...base(),
              type: "model.rerouted",
              payload: {
                fromModel: event.data.previousModel ?? "unknown",
                toModel: event.data.newModel,
                reason: "session.model_change",
              },
            },
          ];
        case "session.plan_changed":
          return [
            {
              ...base(),
              type: "turn.plan.updated",
              payload: {
                explanation: `Plan ${event.data.operation}d`,
                plan: [],
              },
            },
          ];
        case "session.workspace_file_changed":
          return [
            {
              ...base(),
              type: "files.persisted",
              payload: {
                files: [
                  {
                    filename: event.data.path,
                    fileId: event.data.path,
                  },
                ],
              },
            },
          ];
        case "session.context_changed": {
          const sessionContextMetadata = asRecord(event.data);
          return [
            {
              ...base(),
              type: "thread.metadata.updated",
              payload: sessionContextMetadata ? { metadata: sessionContextMetadata } : {},
            },
          ];
        }
        case "session.usage_info":
          return [
            {
              ...base(),
              type: "thread.token-usage.updated",
              payload: {
                usage: mapSessionUsageInfo(event.data),
              },
            },
          ];
        case "session.task_complete":
          return [
            {
              ...base(),
              type: "task.completed",
              payload: {
                taskId: toRuntimeTaskId(record.threadId) ?? RuntimeTaskId.make(record.threadId),
                status: "completed",
                ...(trimToUndefined(event.data.summary) ? { summary: event.data.summary } : {}),
              },
            },
          ];
        case "assistant.turn_start": {
          // Use the timestamp from when sendTurn() was called (turnSentAt),
          // not the SDK's event.timestamp, to ensure the "Worked for X" timer
          // in the UI reflects actual elapsed time since the user sent their message.
          const turnStartBase = (input?: {
            readonly turnId?: TurnId | undefined;
            readonly providerTurnId?: TurnId | undefined;
          }) =>
            withRefs({
              threadId: record.threadId,
              eventId: EventId.make(event.id),
              createdAt: record.turnSentAt ?? event.timestamp,
              turnId: resolveOrchestrationTurnId(input?.providerTurnId ?? input?.turnId),
              providerTurnId: input?.providerTurnId ?? input?.turnId,
              itemId: undefined,
              requestId: undefined,
              rawMethod: event.type,
              rawPayload: event,
            });
          return [
            {
              ...turnStartBase({ providerTurnId: toTurnId(event.data.turnId) }),
              type: "turn.started",
              payload: record.model ? { model: record.model } : {},
            },
            {
              ...turnStartBase({ providerTurnId: toTurnId(event.data.turnId) }),
              type: "session.state.changed",
              payload: {
                state: "running",
                reason: "assistant.turn_start",
              },
            },
          ];
        }
        case "assistant.reasoning":
          return [
            {
              ...base({ itemId: event.data.reasoningId }),
              type: "item.completed",
              payload: {
                itemType: "reasoning",
                status: "completed",
                title: "Reasoning",
                detail: trimToUndefined(event.data.content),
                data: event.data,
              },
            },
          ];
        case "assistant.reasoning_delta":
          return [
            {
              ...base({ itemId: event.data.reasoningId }),
              type: "content.delta",
              payload: {
                streamKind: "reasoning_text",
                delta: event.data.deltaContent,
              },
            },
          ];
        case "assistant.message":
          return [
            {
              ...base({ itemId: event.data.messageId }),
              type: "item.completed",
              payload: {
                itemType: "assistant_message",
                status: "completed",
                title: "Assistant message",
                detail: trimToUndefined(event.data.content),
                data: event.data,
              },
            },
          ];
        case "assistant.message_delta":
          return [
            {
              ...base({ itemId: event.data.messageId }),
              type: "content.delta",
              payload: {
                streamKind: "assistant_text",
                delta: event.data.deltaContent,
              },
            },
          ];
        case "assistant.turn_end":
          return [];
        case "assistant.usage": {
          const completionRefs = completionTurnRefs(record);
          const completionBase =
            completionRefs.turnId || completionRefs.providerTurnId ? base(completionRefs) : base();
          return [
            {
              ...completionBase,
              type: "thread.token-usage.updated",
              payload: {
                usage: mapAssistantUsage(event.data),
              },
            },
          ];
        }
        case "abort": {
          const abortedTurnRefs = completionTurnRefs(record);
          const abortedBase =
            abortedTurnRefs.turnId || abortedTurnRefs.providerTurnId
              ? base(abortedTurnRefs)
              : base();
          return [
            {
              ...abortedBase,
              type: "turn.aborted",
              payload: {
                reason: event.data.reason,
              },
            },
          ];
        }
        case "tool.execution_start":
          return [
            {
              ...base({ itemId: event.data.toolCallId }),
              type: "item.started",
              payload: {
                itemType: itemTypeFromToolEvent(event),
                status: "inProgress",
                title: event.data.toolName ?? "Tool call",
                ...(toolDetailFromEvent(event.data)
                  ? { detail: toolDetailFromEvent(event.data) }
                  : {}),
                data: event.data,
              },
            },
          ];
        case "tool.execution_progress":
          return [
            {
              ...base({ itemId: event.data.toolCallId }),
              type: "tool.progress",
              payload: {
                toolUseId: event.data.toolCallId,
                summary: event.data.progressMessage,
              },
            },
          ];
        case "tool.execution_partial_result":
          return [
            {
              ...base({ itemId: event.data.toolCallId }),
              type: "tool.progress",
              payload: {
                toolUseId: event.data.toolCallId,
                summary: event.data.partialOutput,
              },
            },
          ];
        case "tool.execution_complete": {
          const contents = event.data.result?.contents ?? [];
          const hasTerminal = contents.some(
            (content: { type: string }) => content.type === "terminal",
          );
          // Extract image content blocks as separate image_view events
          const imageEvents: ProviderRuntimeEvent[] = contents
            .filter((content: { type: string }) => content.type === "image")
            .map(
              (content: {
                type: string;
                data?: string;
                mimeType?: string;
                description?: string;
              }) => ({
                ...base({ itemId: event.data.toolCallId }),
                type: "item.completed" as const,
                payload: {
                  itemType: "image_view" as const,
                  status: "completed" as const,
                  title: trimToUndefined(content.description) ?? "Image",
                  data: {
                    base64: content.data,
                    mimeType: content.mimeType,
                    description: content.description,
                  },
                },
              }),
            );
          // Extract audio content blocks
          const audioEvents: ProviderRuntimeEvent[] = contents
            .filter((content: { type: string }) => content.type === "audio")
            .map((content: { type: string; data?: string; mimeType?: string }) => ({
              ...base({ itemId: event.data.toolCallId }),
              type: "item.completed" as const,
              payload: {
                itemType: "dynamic_tool_call" as const,
                status: "completed" as const,
                title: "Audio",
                data: {
                  contentType: "audio",
                  base64: content.data,
                  mimeType: content.mimeType,
                },
              },
            }));
          // Extract file/resource_link content blocks
          const fileEvents: ProviderRuntimeEvent[] = contents
            .filter(
              (content: { type: string }) =>
                content.type === "resource_link" || content.type === "resource",
            )
            .map(
              (content: {
                type: string;
                name?: string;
                uri?: string;
                title?: string;
                description?: string;
              }) => ({
                ...base({ itemId: event.data.toolCallId }),
                type: "item.completed" as const,
                payload: {
                  itemType: "dynamic_tool_call" as const,
                  status: "completed" as const,
                  title: content.name ?? content.title ?? content.uri ?? "Resource",
                  detail: trimToUndefined(content.description),
                  data: content,
                },
              }),
            );
          return [
            {
              ...base({ itemId: event.data.toolCallId }),
              type: "item.completed",
              payload: {
                itemType: hasTerminal ? "command_execution" : "dynamic_tool_call",
                status: event.data.success ? "completed" : "failed",
                title: record.toolTitlesByCallId.get(event.data.toolCallId) ?? "Tool call",
                ...(trimToUndefined(event.data.result?.content)
                  ? { detail: event.data.result?.content }
                  : {}),
                data: event.data,
              },
            },
            ...imageEvents,
            ...audioEvents,
            ...fileEvents,
            ...(trimToUndefined(event.data.result?.content)
              ? [
                  {
                    ...base({ itemId: event.data.toolCallId }),
                    type: "tool.summary" as const,
                    payload: {
                      summary: event.data.result?.content ?? "",
                      precedingToolUseIds: [event.data.toolCallId],
                    },
                  },
                ]
              : []),
          ];
        }
        case "skill.invoked":
          return [
            {
              ...base(),
              type: "task.progress",
              payload: {
                taskId: toRuntimeTaskId(event.data.name) ?? RuntimeTaskId.make(event.data.name),
                description: `Invoked skill ${event.data.name}`,
              },
            },
          ];
        case "subagent.started":
          return [
            {
              ...base(),
              type: "task.started",
              payload: {
                taskId:
                  toRuntimeTaskId(event.data.toolCallId) ??
                  RuntimeTaskId.make(event.data.toolCallId),
                description: trimToUndefined(event.data.agentDescription),
                taskType: "subagent",
              },
            },
          ];
        case "subagent.completed":
          return [
            {
              ...base(),
              type: "task.completed",
              payload: {
                taskId:
                  toRuntimeTaskId(event.data.toolCallId) ??
                  RuntimeTaskId.make(event.data.toolCallId),
                status: "completed",
                ...(trimToUndefined(event.data.agentDisplayName)
                  ? { summary: event.data.agentDisplayName }
                  : {}),
              },
            },
          ];
        case "subagent.failed":
          return [
            {
              ...base(),
              type: "task.completed",
              payload: {
                taskId:
                  toRuntimeTaskId(event.data.toolCallId) ??
                  RuntimeTaskId.make(event.data.toolCallId),
                status: "failed",
                ...(trimToUndefined(event.data.error) ? { summary: event.data.error } : {}),
              },
            },
          ];
        case "session.compaction_start":
          return [
            {
              ...base(),
              type: "session.state.changed",
              payload: {
                state: "waiting",
                reason: "session.compaction_start",
                detail: event.data,
              },
            },
          ];
        case "session.compaction_complete": {
          const compactionEvents: ProviderRuntimeEvent[] = [
            {
              ...base(),
              type: "thread.state.changed",
              payload: {
                state: "compacted",
                detail: event.data,
              },
            },
          ];
          if (event.data.success === false && trimToUndefined(event.data.error)) {
            compactionEvents.push({
              ...base(),
              type: "runtime.warning",
              payload: {
                message: `Context compaction failed: ${event.data.error}`,
                detail: event.data,
              },
            });
          }
          return compactionEvents;
        }
        case "session.truncation":
          return [
            {
              ...base(),
              type: "runtime.warning",
              payload: {
                message: `Context truncated: ${event.data.tokensRemovedDuringTruncation} tokens removed (${event.data.messagesRemovedDuringTruncation} messages), ${event.data.postTruncationTokensInMessages}/${event.data.tokenLimit} tokens remaining.`,
                detail: event.data,
              },
            },
          ];
        case "session.skills_loaded": {
          const skills = (event.data.skills ?? [])
            .map(mapSdkSkillToServerProviderSkill)
            .filter((s): s is ServerProviderSkill => s !== null);
          mergeDiscoveredSkills(skills);
          return [];
        }
        case "exit_plan_mode.requested":
          return [
            {
              ...base({ turnId: currentSyntheticTurnId(record) }),
              type: "turn.proposed.completed",
              payload: {
                planMarkdown: event.data.planContent ?? event.data.summary ?? "",
              },
            },
          ];
        case "exit_plan_mode.completed":
          return [];
        case "system.notification": {
          const kind = event.data.kind;
          if (kind.type === "agent_completed") {
            return [
              {
                ...base(),
                type: "task.completed",
                payload: {
                  taskId: toRuntimeTaskId(kind.agentId) ?? RuntimeTaskId.make(kind.agentId),
                  status: kind.status === "failed" ? "failed" : "completed",
                  ...(trimToUndefined(kind.description) ? { summary: kind.description } : {}),
                },
              },
            ];
          }
          if (kind.type === "shell_completed" || kind.type === "shell_detached_completed") {
            return [
              {
                ...base(),
                type: "task.completed",
                payload: {
                  taskId: toRuntimeTaskId(kind.shellId) ?? RuntimeTaskId.make(kind.shellId),
                  status: "completed",
                  ...(trimToUndefined(kind.description) ? { summary: kind.description } : {}),
                },
              },
            ];
          }
          // agent_idle and unknown kinds — surface as info
          return [
            {
              ...base(),
              type: "runtime.warning",
              payload: {
                message: event.data.content.replace(/<\/?system_notification>/g, "").trim(),
                detail: event.data,
              },
            },
          ];
        }
        case "system.message":
          return [];
        case "command.execute":
          return [
            {
              ...base({ requestId: event.data.requestId }),
              type: "runtime.warning",
              payload: {
                message: `Command: ${event.data.command}`,
                detail: event.data,
              },
            },
          ];
        case "command.completed":
          return [];
        case "command.queued":
          return [
            {
              ...base({ requestId: event.data.requestId }),
              type: "runtime.warning",
              payload: {
                message: `Queued command: ${event.data.command}`,
                detail: event.data,
              },
            },
          ];
        default:
          return [];
      }
    };

    const createInteractionHandlers = (
      threadId: ThreadId,
      getCurrentTurnId: () => TurnId | undefined,
      getRuntimeMode: () => ProviderSession["runtimeMode"],
      getInteractionMode: () => "default" | "plan" | undefined,
      pendingApprovalResolvers: Map<string, PendingApprovalRequest>,
      pendingUserInputResolvers: Map<string, PendingUserInputRequest>,
    ) => {
      const onPermissionRequest = (request: PermissionRequest) => {
        const permissionRequest = request as CopilotPermissionRequest;
        // Plan mode: trust the SDK's mode.set("plan") to guide the agent via
        // system prompt. Do NOT hard-block tools — the SDK and VS Code don't
        // enforce plan mode at the permission level either. If the agent tries
        // tools in plan mode, let the normal permission flow handle it:
        // - full-access: auto-approve (agent self-corrects via system prompt)
        // - supervised: show dialog to user (user decides)
        //
        // Previous approach silently rejected shell/write in plan mode,
        // causing the agent to stop without feedback. See case study
        // 2026-04-26-fresh-branch-reconciliation.md.

        return getRuntimeMode() === "full-access"
          ? Promise.resolve(toSdkPermissionRequestResult({ kind: "approve-once" }))
          : new Promise<PermissionRequestResult>((resolve) => {
              const requestId = `copilot-approval-${randomUUID()}`;
              const turnId = getCurrentTurnId();
              pendingApprovalResolvers.set(requestId, {
                request: permissionRequest,
                requestType: requestTypeFromPermissionRequest(permissionRequest),
                turnId,
                resolve: (result) => resolve(toSdkPermissionRequestResult(result)),
              });
              void emitRuntimeEvents([
                makeSyntheticEvent(
                  threadId,
                  "request.opened",
                  {
                    requestType: requestTypeFromPermissionRequest(permissionRequest),
                    ...(requestDetailFromPermissionRequest(permissionRequest)
                      ? { detail: requestDetailFromPermissionRequest(permissionRequest) }
                      : {}),
                    args: permissionRequest,
                  },
                  { requestId, turnId },
                ),
              ]);
            });
      };

      const onUserInputRequest = (request: CopilotUserInputRequest) =>
        new Promise<CopilotUserInputResponse>((resolve) => {
          const requestId = `copilot-user-input-${randomUUID()}`;
          const turnId = getCurrentTurnId();
          pendingUserInputResolvers.set(requestId, {
            request,
            turnId,
            resolve,
          });
          void emitRuntimeEvents([
            makeSyntheticEvent(
              threadId,
              "user-input.requested",
              {
                questions: [
                  {
                    id: USER_INPUT_QUESTION_ID,
                    header: USER_INPUT_QUESTION_HEADER,
                    question: request.question,
                    options: (request.choices ?? []).map((choice: string) => ({
                      label: choice,
                      description: choice,
                    })),
                  },
                ],
              },
              { requestId, turnId },
            ),
          ]);
        });

      return {
        onPermissionRequest,
        onUserInputRequest,
      };
    };

    const validateSessionConfiguration = (input: {
      readonly client: CopilotClientHandle;
      readonly threadId: ThreadId;
      readonly model: string | undefined;
      readonly reasoningEffort: ReasoningEffort | undefined;
    }) =>
      Effect.gen(function* () {
        if (!input.model && !input.reasoningEffort) {
          return;
        }

        yield* Effect.tryPromise({
          try: () => input.client.start(),
          catch: (cause) =>
            new ProviderAdapterProcessError({
              provider: PROVIDER,
              threadId: input.threadId,
              detail: toMessage(cause, "Failed to start GitHub Copilot client."),
              cause,
            }),
        });

        const supportedModels = mapSupportedModelsById(
          yield* Effect.tryPromise({
            try: () => input.client.listModels(),
            catch: (cause) =>
              new ProviderAdapterProcessError({
                provider: PROVIDER,
                threadId: input.threadId,
                detail: toMessage(cause, "Failed to load GitHub Copilot model metadata."),
                cause,
              }),
          }),
        );
        const selectedModel = input.model ? supportedModels.get(input.model) : undefined;

        if (input.model && !selectedModel) {
          return yield* new ProviderAdapterValidationError({
            provider: PROVIDER,
            operation: "session.model",
            issue: `GitHub Copilot model '${input.model}' is not available in the current Copilot runtime.`,
          });
        }

        if (!input.reasoningEffort) {
          return;
        }

        if (!selectedModel) {
          return yield* new ProviderAdapterValidationError({
            provider: PROVIDER,
            operation: "session.reasoningEffort",
            issue:
              "GitHub Copilot reasoning effort requires an explicit supported model selection.",
          });
        }

        const supportedReasoningEfforts = selectedModel.supportedReasoningEfforts ?? [];
        if (supportedReasoningEfforts.length === 0) {
          return yield* new ProviderAdapterValidationError({
            provider: PROVIDER,
            operation: "session.reasoningEffort",
            issue: `GitHub Copilot model '${selectedModel.id}' does not support reasoning effort configuration.`,
          });
        }

        if (!supportedReasoningEfforts.includes(input.reasoningEffort)) {
          return yield* new ProviderAdapterValidationError({
            provider: PROVIDER,
            operation: "session.reasoningEffort",
            issue: `GitHub Copilot model '${selectedModel.id}' does not support reasoning effort '${input.reasoningEffort}'.`,
          });
        }
      });

    const reconfigureSession = (
      record: ActiveCopilotSession,
      input: {
        readonly model: string | undefined;
        readonly reasoningEffort: ReasoningEffort | undefined;
      },
    ) =>
      Effect.tryPromise({
        try: async () => {
          const sessionId = record.session.sessionId;
          const previousSession = record.session;
          const previousUnsubscribe = record.unsubscribe;
          previousUnsubscribe();
          await previousSession.destroy();

          const handlers = createInteractionHandlers(
            record.threadId,
            () => record.currentTurnId,
            () => record.runtimeMode,
            () => record.interactionMode,
            record.pendingApprovalResolvers,
            record.pendingUserInputResolvers,
          );
          const nextSession = await record.client.resumeSession(sessionId, {
            ...handlers,
            ...(input.model ? { model: input.model } : {}),
            ...(input.reasoningEffort ? { reasoningEffort: input.reasoningEffort } : {}),
            ...(record.cwd ? { workingDirectory: record.cwd } : {}),
            ...(record.configDir ? { configDir: record.configDir } : {}),
            enableConfigDiscovery: true,
            streaming: true,
          });

          record.session = nextSession;
          record.model = input.model;
          record.reasoningEffort = input.reasoningEffort;
          record.interactionMode = undefined;
          record.updatedAt = DateTime.formatIso(DateTime.nowUnsafe());
          record.unsubscribe = nextSession.on((event) => {
            handleSessionEvent(record, event);
          });
        },
        catch: (cause) =>
          new ProviderAdapterRequestError({
            provider: PROVIDER,
            method: "session.reconfigure",
            detail: toMessage(cause, "Failed to reconfigure GitHub Copilot session."),
            cause,
          }),
      });

    const handleSessionEvent = (record: ActiveCopilotSession, event: SessionEvent) => {
      record.updatedAt = event.timestamp;
      if (event.type === "assistant.turn_start") {
        beginCopilotTurn(record, TurnId.make(event.data.turnId));
      }
      if (event.type === "assistant.usage") {
        recordTurnUsage(record, event.data);
      }
      if (event.type === "session.error") {
        record.lastError = event.data.message;
      }
      if (event.type === "session.model_change") {
        record.model = event.data.newModel;
      }
      if (event.type === "session.mode_changed") {
        record.interactionMode = toInteractionMode(event.data.newMode);
      }
      if (event.type === "tool.execution_start" && trimToUndefined(event.data.toolName)) {
        record.toolTitlesByCallId.set(event.data.toolCallId, trimToUndefined(event.data.toolName)!);
      }

      void writeNativeEvent(record.threadId, event);
      const runtimeEvents = mapSessionEvent(record, event);
      if (runtimeEvents.length > 0) {
        void emitRuntimeEvents(runtimeEvents);
      }
      if (event.type === "session.plan_changed" && event.data.operation !== "delete") {
        void runPromise(emitLatestProposedPlan(record)).catch((cause) => {
          void emitRuntimeEvents([
            makeSyntheticEvent(
              record.threadId,
              "runtime.warning",
              {
                message: "Failed to read GitHub Copilot plan.",
                detail: toMessage(cause, "Failed to read GitHub Copilot plan."),
              },
              { turnId: currentSyntheticTurnId(record) },
            ),
          ]);
        });
      }
      if (event.type === "tool.execution_complete") {
        record.toolTitlesByCallId.delete(event.data.toolCallId);
      }
      if (event.type === "assistant.turn_end") {
        markTurnAwaitingCompletion(record);
      }
      if (event.type === "abort" || event.type === "session.idle") {
        clearTurnTracking(record);
        record.turnSentAt = undefined;
      }
    };

    const getSessionRecord = (threadId: ThreadId) => {
      const record = sessions.get(threadId);
      if (!record) {
        return Effect.fail(
          new ProviderAdapterSessionNotFoundError({ provider: PROVIDER, threadId }),
        );
      }
      return Effect.succeed(record);
    };

    const stopRecord = async (record: ActiveCopilotSession) => {
      record.unsubscribe();
      try {
        await record.session.destroy();
      } catch {
        // best effort
      }
      try {
        await record.client.stop();
      } catch {
        // best effort
      }
      for (const pending of record.pendingApprovalResolvers.values()) {
        pending.resolve({ kind: "user-not-available" });
      }
      for (const pending of record.pendingUserInputResolvers.values()) {
        pending.resolve({ answer: "", wasFreeform: true });
      }
      sessions.delete(record.threadId);
    };

    const startSession: CopilotAdapterShape["startSession"] = (input) =>
      Effect.gen(function* () {
        const copilotSettings = yield* serverSettings.getSettings.pipe(
          Effect.map((settings) => settings.providers.copilot),
          Effect.mapError(
            (cause) =>
              new ProviderAdapterProcessError({
                provider: PROVIDER,
                threadId: input.threadId,
                detail: toMessage(cause, "Failed to load GitHub Copilot settings."),
                cause,
              }),
          ),
        );
        const requestedModelSelection = input.modelSelection ?? undefined;
        const sessionConfiguration: CopilotSessionConfiguration = {
          model: requestedModelSelection?.model,
          reasoningEffort: getCopilotReasoningEffortFromSelection(requestedModelSelection),
        };
        if (input.provider !== undefined && input.provider !== PROVIDER) {
          return yield* new ProviderAdapterValidationError({
            provider: PROVIDER,
            operation: "startSession",
            issue: `Expected provider '${PROVIDER}', received '${input.provider}'.`,
          });
        }

        const existing = sessions.get(input.threadId);
        if (existing) {
          return {
            provider: PROVIDER,
            status: "ready",
            runtimeMode: existing.runtimeMode,
            ...(existing.cwd ? { cwd: existing.cwd } : {}),
            ...(existing.model ? { model: existing.model } : {}),
            threadId: input.threadId,
            resumeCursor: existing.session.sessionId,
            createdAt: existing.createdAt,
            updatedAt: existing.updatedAt,
            ...(existing.lastError ? { lastError: existing.lastError } : {}),
          } satisfies ProviderSession;
        }

        const cliPath =
          normalizeCopilotCliPathOverride(copilotSettings.binaryPath) ??
          resolveBundledCopilotCliPath();
        const configDir = undefined;
        const mcpServers = yield* Effect.tryPromise({
          try: () => loadCopilotMcpServers(configDir),
          catch: (cause) =>
            new ProviderAdapterProcessError({
              provider: PROVIDER,
              threadId: input.threadId,
              detail: toMessage(cause, "Failed to load GitHub Copilot MCP configuration."),
              cause,
            }),
        });
        const resumeSessionId = extractResumeSessionId(input.resumeCursor);
        const clientOptions: CopilotClientOptions = {
          ...(cliPath ? { cliPath } : {}),
          ...(input.cwd ? { cwd: input.cwd } : {}),
          logLevel: "error",
        };
        const client = options?.clientFactory?.(clientOptions) ?? new CopilotClient(clientOptions);
        const pendingApprovalResolvers = new Map<string, PendingApprovalRequest>();
        const pendingUserInputResolvers = new Map<string, PendingUserInputRequest>();
        let sessionRecord: ActiveCopilotSession | undefined;
        const handlers = createInteractionHandlers(
          input.threadId,
          () => sessionRecord?.currentTurnId,
          () => sessionRecord?.runtimeMode ?? input.runtimeMode,
          () => sessionRecord?.interactionMode,
          pendingApprovalResolvers,
          pendingUserInputResolvers,
        );

        yield* validateSessionConfiguration({
          client,
          threadId: input.threadId,
          ...sessionConfiguration,
        });

        const session = yield* Effect.tryPromise({
          try: async () => {
            if (resumeSessionId) {
              return client.resumeSession(resumeSessionId, {
                ...handlers,
                ...(sessionConfiguration.model ? { model: sessionConfiguration.model } : {}),
                ...(sessionConfiguration.reasoningEffort
                  ? { reasoningEffort: sessionConfiguration.reasoningEffort }
                  : {}),
                ...(input.cwd ? { workingDirectory: input.cwd } : {}),
                ...(configDir ? { configDir } : {}),
                ...(mcpServers ? { mcpServers } : {}),
                enableConfigDiscovery: true,
                streaming: true,
              });
            }
            return client.createSession({
              ...handlers,
              ...(sessionConfiguration.model ? { model: sessionConfiguration.model } : {}),
              ...(sessionConfiguration.reasoningEffort
                ? { reasoningEffort: sessionConfiguration.reasoningEffort }
                : {}),
              ...(input.cwd ? { workingDirectory: input.cwd } : {}),
              ...(configDir ? { configDir } : {}),
              ...(mcpServers ? { mcpServers } : {}),
              enableConfigDiscovery: true,
              streaming: true,
            });
          },
          catch: (cause) =>
            new ProviderAdapterProcessError({
              provider: PROVIDER,
              threadId: input.threadId,
              detail: toMessage(cause, "Failed to start GitHub Copilot session."),
              cause,
            }),
        });

        const record = createSessionRecord({
          threadId: input.threadId,
          client,
          session,
          runtimeMode: input.runtimeMode,
          pendingApprovalResolvers,
          pendingUserInputResolvers,
          cwd: input.cwd,
          configDir,
          ...sessionConfiguration,
        });
        const unsubscribe = session.on((event) => {
          handleSessionEvent(record, event);
        });
        record.unsubscribe = unsubscribe;
        sessionRecord = record;
        sessions.set(input.threadId, record);

        yield* Queue.offerAll(runtimeEventQueue, [
          makeSyntheticEvent(input.threadId, "session.started", {
            message: resumeSessionId
              ? "Resumed GitHub Copilot session"
              : "Started GitHub Copilot session",
            resume: { sessionId: session.sessionId },
          }),
          makeSyntheticEvent(input.threadId, "session.configured", {
            config: {
              ...(input.cwd ? { cwd: input.cwd } : {}),
              ...(sessionConfiguration.model ? { model: sessionConfiguration.model } : {}),
              ...(sessionConfiguration.reasoningEffort
                ? { reasoningEffort: sessionConfiguration.reasoningEffort }
                : {}),
              ...(configDir ? { configDir } : {}),
              streaming: true,
            },
          }),
          makeSyntheticEvent(input.threadId, "thread.started", {
            providerThreadId: session.sessionId,
          }),
          makeSyntheticEvent(input.threadId, "session.state.changed", {
            state: "ready",
            reason: "session.started",
          }),
        ]);

        // Non-blocking skill discovery + reload after session start.
        // 1. Reload skills to pick up any new SKILL.md files in the workspace
        // 2. List skills to populate the discovery cache
        // Belt-and-suspenders alongside the session.skills_loaded event handler.
        void (async () => {
          try {
            const rpcSkills = (session.rpc as CopilotSkillsRpc).skills;
            // Reload first to discover new workspace skills
            await rpcSkills?.reload?.().catch(() => {});
            // Then list to populate the cache
            const skillsResult = await rpcSkills?.list?.();
            if (Array.isArray(skillsResult?.skills) && skillsResult.skills.length > 0) {
              const mapped = skillsResult.skills
                .map(mapSdkSkillToServerProviderSkill)
                .filter((s): s is ServerProviderSkill => s !== null);
              mergeDiscoveredSkills(mapped);
            }
          } catch (err: unknown) {
            const message = err instanceof Error ? err.message : String(err);
            // @effect-diagnostics-next-line effect/globalConsole:off
            console.warn("[CopilotAdapter] rpc.skills discovery failed:", message);
          }
        })();

        return {
          provider: PROVIDER,
          status: "ready",
          runtimeMode: input.runtimeMode,
          ...(input.cwd ? { cwd: input.cwd } : {}),
          ...(sessionConfiguration.model ? { model: sessionConfiguration.model } : {}),
          threadId: input.threadId,
          resumeCursor: session.sessionId,
          createdAt: record.createdAt,
          updatedAt: record.updatedAt,
        } satisfies ProviderSession;
      });

    const sendTurn: CopilotAdapterShape["sendTurn"] = (input) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(input.threadId);
        const requestedModelSelection = input.modelSelection ?? undefined;
        const explicitReasoningEffort =
          getCopilotReasoningEffortFromSelection(requestedModelSelection);
        const nextModel = requestedModelSelection?.model ?? record.model;
        const nextReasoningEffort =
          explicitReasoningEffort !== undefined
            ? explicitReasoningEffort
            : requestedModelSelection?.model !== undefined &&
                requestedModelSelection.model !== record.model
              ? undefined
              : record.reasoningEffort;
        const attachments = (input.attachments ?? []).map((attachment) => {
          const attachmentPath = resolveAttachmentPath({
            attachmentsDir: serverConfig.attachmentsDir,
            attachment,
          });
          if (!attachmentPath) {
            throw new ProviderAdapterRequestError({
              provider: PROVIDER,
              method: "session.send",
              detail: `Invalid attachment id '${attachment.id}'.`,
            });
          }
          return {
            type: "file" as const,
            path: attachmentPath,
            displayName: attachment.name,
          };
        });

        yield* validateSessionConfiguration({
          client: record.client,
          threadId: input.threadId,
          model: nextModel,
          reasoningEffort: nextReasoningEffort,
        });

        if (nextModel !== record.model || nextReasoningEffort !== record.reasoningEffort) {
          yield* reconfigureSession(record, {
            model: nextModel,
            reasoningEffort: nextReasoningEffort,
          });
        }

        const interactionMode = input.interactionMode ?? record.interactionMode ?? "default";
        yield* syncInteractionMode(record, interactionMode);

        const turnId = TurnId.make(`copilot-turn-${randomUUID()}`);
        const turnSentAt = DateTime.formatIso(DateTime.nowUnsafe());
        record.pendingTurnIds.push(turnId);
        record.currentTurnId = turnId;
        record.currentProviderTurnId = undefined;
        record.turnSentAt = turnSentAt;

        yield* Effect.tryPromise({
          try: () =>
            record.session.send({
              prompt: input.input ?? "",
              ...(attachments.length > 0 ? { attachments } : {}),
              mode: "immediate",
            }),
          catch: (cause) =>
            new ProviderAdapterRequestError({
              provider: PROVIDER,
              method: "session.send",
              detail: toMessage(cause, "Failed to send GitHub Copilot turn."),
              cause,
            }),
        }).pipe(
          Effect.tapError(() =>
            Effect.sync(() => {
              record.pendingTurnIds = record.pendingTurnIds.filter(
                (candidate) => candidate !== turnId,
              );
              if (record.currentTurnId === turnId) {
                record.currentTurnId = undefined;
              }
            }),
          ),
        );

        record.updatedAt = DateTime.formatIso(DateTime.nowUnsafe());

        return {
          threadId: input.threadId,
          turnId,
          resumeCursor: record.session.sessionId,
        } satisfies ProviderTurnStartResult;
      });

    const interruptTurn: CopilotAdapterShape["interruptTurn"] = (threadId) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(threadId);
        yield* Effect.tryPromise({
          try: () => record.session.abort(),
          catch: (cause) =>
            new ProviderAdapterRequestError({
              provider: PROVIDER,
              method: "session.abort",
              detail: toMessage(cause, "Failed to interrupt GitHub Copilot turn."),
              cause,
            }),
        });
      });

    const respondToRequest: CopilotAdapterShape["respondToRequest"] = (
      threadId,
      requestId,
      decision,
    ) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(threadId);
        const pending = record.pendingApprovalResolvers.get(requestId);
        if (!pending) {
          return yield* new ProviderAdapterRequestError({
            provider: PROVIDER,
            method: "session.permission.respond",
            detail: `Unknown pending GitHub Copilot approval request '${requestId}'.`,
          });
        }
        record.pendingApprovalResolvers.delete(requestId);
        const resolution = approvalDecisionToPermissionResult(decision, pending.request);
        pending.resolve(resolution);
        yield* Queue.offer(
          runtimeEventQueue,
          makeSyntheticEvent(
            threadId,
            "request.resolved",
            {
              requestType: pending.requestType,
              decision,
              resolution,
            },
            { requestId, turnId: pending.turnId },
          ),
        );
      });

    const respondToUserInput: CopilotAdapterShape["respondToUserInput"] = (
      threadId,
      requestId,
      answers,
    ) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(threadId);
        const pending = record.pendingUserInputResolvers.get(requestId);
        if (!pending) {
          return yield* new ProviderAdapterRequestError({
            provider: PROVIDER,
            method: "session.userInput.respond",
            detail: `Unknown pending GitHub Copilot user-input request '${requestId}'.`,
          });
        }
        record.pendingUserInputResolvers.delete(requestId);
        pending.resolve(resolveUserInputAnswer(pending, answers));
        yield* Queue.offer(
          runtimeEventQueue,
          makeSyntheticEvent(
            threadId,
            "user-input.resolved",
            {
              answers,
            },
            { requestId, turnId: pending.turnId },
          ),
        );
      });

    const stopSession: CopilotAdapterShape["stopSession"] = (threadId) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(threadId);
        yield* Effect.tryPromise({
          try: async () => {
            await stopRecord(record);
          },
          catch: (cause) =>
            new ProviderAdapterProcessError({
              provider: PROVIDER,
              threadId,
              detail: toMessage(cause, "Failed to stop GitHub Copilot session."),
              cause,
            }),
        });
      });

    const listSessions: CopilotAdapterShape["listSessions"] = () =>
      Effect.sync(() =>
        Array.from(sessions.values()).map((record) => {
          const session: ProviderSession = {
            provider: PROVIDER,
            status: record.currentTurnId ? "running" : "ready",
            runtimeMode: record.runtimeMode,
            threadId: record.threadId,
            resumeCursor: record.session.sessionId,
            createdAt: record.createdAt,
            updatedAt: record.updatedAt,
          };
          if (record.cwd) {
            Object.assign(session, { cwd: record.cwd });
          }
          if (record.model) {
            Object.assign(session, { model: record.model });
          }
          if (record.currentTurnId) {
            Object.assign(session, { activeTurnId: record.currentTurnId });
          }
          if (record.lastError) {
            Object.assign(session, { lastError: record.lastError });
          }
          return session;
        }),
      );

    const hasSession: CopilotAdapterShape["hasSession"] = (threadId) =>
      Effect.sync(() => sessions.has(threadId));

    const readThread: CopilotAdapterShape["readThread"] = (threadId) =>
      Effect.gen(function* () {
        const record = yield* getSessionRecord(threadId);
        return yield* Effect.tryPromise({
          try: async () => {
            const messages = await record.session.getMessages();
            return mapHistoryToTurns(threadId, messages);
          },
          catch: (cause) =>
            new ProviderAdapterRequestError({
              provider: PROVIDER,
              method: "session.getMessages",
              detail: toMessage(cause, "Failed to read GitHub Copilot thread history."),
              cause,
            }),
        });
      });

    const rollbackThread: CopilotAdapterShape["rollbackThread"] = (_threadId) =>
      Effect.fail(
        new ProviderAdapterRequestError({
          provider: PROVIDER,
          method: "thread.rollback",
          detail:
            "GitHub Copilot SDK does not expose a supported conversation rollback API for existing sessions.",
        }),
      );

    const stopAll: CopilotAdapterShape["stopAll"] = () =>
      Effect.tryPromise({
        try: async () => {
          await Promise.all(Array.from(sessions.values()).map((record) => stopRecord(record)));
        },
        catch: (cause) =>
          new ProviderAdapterProcessError({
            provider: PROVIDER,
            threadId: ThreadId.make("_all"),
            detail: toMessage(cause, "Failed to stop GitHub Copilot sessions."),
            cause,
          }),
      });

    const setSkillEnabled: CopilotAdapterShape["setSkillEnabled"] = (skillName, enabled) =>
      Effect.tryPromise({
        try: async () => {
          // Find any active session to use its RPC interface
          const record = Array.from(sessions.values()).find((r) => r.session);
          if (!record?.session) {
            throw new Error("No active Copilot session — cannot toggle skill.");
          }
          const rpc = record.session as unknown as CopilotSkillsRpc;
          if (enabled) {
            if (!rpc.skills?.enable) {
              throw new Error("Copilot SDK does not support rpc.skills.enable()");
            }
            await rpc.skills.enable({ name: skillName });
          } else {
            if (!rpc.skills?.disable) {
              throw new Error("Copilot SDK does not support rpc.skills.disable()");
            }
            await rpc.skills.disable({ name: skillName });
          }
          // Update local skill state
          for (const skill of discoveredCopilotSkills) {
            if (skill.name === skillName) {
              (skill as { enabled: boolean }).enabled = enabled;
            }
          }
          // Reload skills list to get fresh state from SDK
          if (rpc.skills?.reload) {
            await rpc.skills.reload();
          }
        },
        catch: (cause) =>
          new ProviderAdapterProcessError({
            provider: PROVIDER,
            threadId: ThreadId.make("_skill-toggle"),
            detail: toMessage(cause, `Failed to ${enabled ? "enable" : "disable"} skill "${skillName}".`),
            cause,
          }),
      });

    return {
      provider: PROVIDER,
      capabilities: {
        sessionModelSwitch: "in-session",
      },
      startSession,
      sendTurn,
      interruptTurn,
      respondToRequest,
      respondToUserInput,
      stopSession,
      listSessions,
      hasSession,
      readThread,
      rollbackThread,
      stopAll,
      setSkillEnabled,
      streamEvents: Stream.fromQueue(runtimeEventQueue),
    } satisfies CopilotAdapterShape;
  });

export const CopilotAdapterLive = Layer.effect(CopilotAdapter, makeCopilotAdapter());

export function makeCopilotAdapterLive(options?: CopilotAdapterLiveOptions) {
  return Layer.effect(CopilotAdapter, makeCopilotAdapter(options));
}

/**
 * CopilotProviderLive - Provider snapshot for GitHub Copilot.
 *
 * Uses @github/copilot-sdk to detect installation, authentication, and
 * available models. Produces a ServerProvider snapshot with runtime models.
 *
 * @module CopilotProviderLive
 */
import { normalizeCopilotCliPathOverride, resolveBundledCopilotCliPath } from "./copilotCliPath.ts";
import { getCopilotDiscoveredSkills } from "./CopilotAdapter.ts";
import type {
  ModelCapabilities,
  ServerProviderModel,
  CopilotSettings,
} from "@t3tools/contracts";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";

import { buildServerProvider, type ServerProviderDraft } from "../providerSnapshot.ts";
import { CopilotProvider } from "../Services/CopilotProvider.ts";

const PROVIDER = "copilot" as const;

const COPILOT_PRESENTATION = {
  displayName: "GitHub Copilot",
} as const;

interface CopilotProviderClientHandle {
  start(): Promise<void>;
  listModels(): Promise<ReadonlyArray<unknown>>;
  stop(): Promise<unknown>;
  readonly rpc?: {
    readonly account?: {
      readonly getQuota?: () => Promise<unknown>;
    };
  };
}

export interface CopilotProviderCheckOptions {
  readonly clientFactory?: (options: Record<string, unknown>) => CopilotProviderClientHandle;
}

interface CopilotProviderStatusCheckError {
  readonly _tag: "CopilotProviderStatusCheckError";
  readonly message: string;
