  return {
    optionDescriptors: [
      {
        id: "effort",
        type: "select" as const,
        label: "Effort",
        options: efforts.map((value: string) => ({
          id: value,
          label: EFFORT_LABEL_MAP[value] ?? value.charAt(0).toUpperCase() + value.slice(1),
          ...(value === (defaultEffort ?? DEFAULT_EFFORT) ? { isDefault: true } : {}),
        })),
      },
    ],
  };
}

